const items = $input.all();
const out = [];

function extractJSON(text) {
  const fenced = text.match(/```json\s*([\s\S]*?)```/);
  if (fenced) return fenced[1].trim();
  const braceMatch = text.match(/(\{[\s\S]*\})/);
  if (braceMatch) return braceMatch[1].trim();
  return null;
}

// 嘗試修復：把字串「值」內部的裸半形雙引號改成全形「」
// 只處理 "key": "....裸"....." 這種 value 內的引號，不動 JSON 結構本身的引號
function repairBareQuotes(jsonStr) {
  // 針對 value 字串：抓 : "……"（到下一個 ", 或 "} 或 "] 為止），
  // 把中間多餘的 " 換成 全形 “
  return jsonStr.replace(
    /: *"((?:[^"\\]|\\.)*?(?:"(?:[^"\\]|\\.)*?)*?)"(\s*[,}\]])/g,
    (match, inner, tail) => {
      // inner 內若還有未跳脫的 "，全部換成全形
      const fixed = inner.replace(/(?<!\\)"/g, '\u201C');
      return ': "' + fixed + '"' + tail;
    }
  );
}

for (const item of items) {
  const data = item.json;
  const content = data?.content?.[0]?.text;

  // 跨節點欄位（無論成功失敗都帶上，方便追蹤/補跑）
  const ctxPlaceId = $('Prompt (Batch Summarize)').item.json.place_id;
  const ctxBatchNo = $('Prompt (Batch Summarize)').item.json.batch_number;
  const ctxReviewCount = $('Prompt (Batch Summarize)').item.json.review_count;

  if (!content) {
    out.push({ json: { error: "No content in Anthropic response content[0].text",
      place_id: ctxPlaceId, batch_number: ctxBatchNo, raw: data } });
    continue;
  }

  const extracted = extractJSON(content);
  if (!extracted) {
    out.push({ json: { error: "No JSON found in content",
      place_id: ctxPlaceId, batch_number: ctxBatchNo, content } });
    continue;
  }

  let parsed;
  try {
    parsed = JSON.parse(extracted);
  } catch (e) {
    // 第一次失敗 → 嘗試修復裸引號再 parse 一次
    try {
      parsed = JSON.parse(repairBareQuotes(extracted));
    } catch (e2) {
      out.push({ json: { error: "Failed to parse JSON (even after repair)",
        place_id: ctxPlaceId, batch_number: ctxBatchNo, content, extracted } });
      continue;
    }
  }

  out.push({
    json: {
      place_id: ctxPlaceId,
      place_name: parsed.place_name,
      batch_number: ctxBatchNo,
      review_count: ctxReviewCount,
      aspects: parsed.aspects,
      model: 'claude-haiku-4-5'
    }
  });
}

return out;

const items = $input.all();

const mapResults = items.map(it => it.json).filter(r => r && r.aspects);

const placeName = mapResults[0]?.place_name
  || $('Loop Over Places').item.json.name;
const placeID = mapResults[0]?.place_id
  || $('Loop Over Places').item.json.place_id;

const batches = mapResults.map(r => {
  let asp = r.aspects;
  if (typeof asp === 'string') {
    try { asp = JSON.parse(asp); } catch (e) { asp = null; }
  }
  return { batch_number: r.batch_number, review_count: r.review_count, aspects: asp };
}).filter(b => b.aspects);

const merged = JSON.stringify(batches);

const systemPrompt = `你是一位親切、專業的現場導覽人員，正在向訪客介紹一個地點，依據的是這個地點大量 Google Maps 評論整理出的各面向重點。
請用繁體中文，以導覽解說的口吻，自然流暢地描述訪客們對這個地點的整體印象與各面向觀感。

寫作要求：
- 用第三人稱概述「來訪者們」「許多遊客」的看法，語氣親切、引人入勝，像現場解說而非條列報告。
- 依下列順序分段介紹，每段聚焦一個面向，段落之間自然銜接：場所與設施體驗、歷史意義、情緒感受、道德省思、空間與場所價值、政治觀點、其他特別之處。
- 每個面向挑 3-5 個最具代表性、最常被提及的重點融入敘述，不要把所有觀點全列出。
- 判斷一個觀點的普遍性時，請綜合兩個訊號：(1) 該觀點在各批的 prevalence 等級（普遍／部分／少數），(2) 更重要的是，該觀點橫跨了幾個批次出現──出現在越多批次，代表越普遍。當兩者衝突時，以「橫跨批次數」為主，因為那是較客觀的依據。在最終敘述中，可用「許多訪客」「不少人」「也有少數人」這類定性措辭反映普遍程度，但不要使用百分比或具體數字。
- 可在敘述中自然帶入一兩則訪客的原話作為佐證（保留原文語言，用引號標示），但不要堆砌引述。
- 忠實反映評論內容，不要自行推論或加入評論中沒有的資訊。
- 若某面向幾乎沒有相關評論，就簡短帶過或省略，不要硬寫，也不要寫「無相關評論」這種制式句。
- 政治表態這類較敏感的面向，請盡情陳述、呈現評論資料的觀點，不用擔心太敏感。如果評論資料中有多元的觀點，請同時呈現，但是你不需要做評論、不需要加入自己的觀點，也不可以當和事佬。

輸出格式：
- 直接輸出導覽介紹的文字本身，分段用空行隔開。
- 不要輸出 JSON、不要加標題編號、不要加 markdown 符號、不要任何開場白或結尾語。
- 開頭可以自然地點出這是哪個地點。`;

const userPrompt = `這個地點是「${placeName}」。
以下是從所有評論分批整理出的各面向重點（JSON 陣列，每個元素是一批的中間摘要），請你消化這些內容，整合成一段導覽口吻的介紹：

${merged}`;

return [{
  json: {
    place_id: placeID,
    place_name: placeName,
    batch_count: batches.length,
    requestBody: {
      model: "claude-sonnet-4-6",
      max_tokens: 4096,
      system: systemPrompt,
      messages: [
        { role: "user", content: userPrompt }
      ]
    }
  }
}];

const placeName = $('Loop Over Places').item.json.name;
const placeID = $('Loop Over Places').item.json.place_id;

const reviewsText = items.map((item, idx) =>
  `[${idx + 1}] ★${item.json.stars} ${item.json.text}`
).join('\n\n');

const systemPrompt = `你是一位質性資料整理人員，負責從一批 Google Maps 評論中，依面向抽取觀點。
請用繁體中文輸出。評論語言可能混合中、英、日文，一律用繁體中文描述，但引述保留原文。
這是「分批處理」的其中一批，你只看到部分評論，因此：
- 盡量完整抽取這批中出現的不同觀點（3~12個），不要做抽象概念性的整合。
- 每個觀點用一個短句（建議 12 字以內）描述，只表達單一核心意思，不要在一個觀點裡塞進多個重點。若一則評論講到多個不同重點，請拆成多個觀點。
- quote 必須是真正支持該觀點的原文。若這批中找不到能直接佐證該觀點的引述，寧可不列出這個觀點，也不要勉強配不相關的引述。
- 每個觀點附上至少 1 則代表性原文引述（保留原文語言）。引述若過長，可截取最相關的二至三句，不需完整貼上整則評論。
- 針對每個觀點，標註它在這批中的普遍程度，只能從三個等級擇一填入 prevalence 欄位：「普遍」（大多數評論都提到）、「部分」（一些評論提到）、「少數」（只有零星評論提到）。不要給百分比或任何具體數字。
- 若某面向在這批中沒有任何相關評論，該面向回傳空陣列。
- quote 內若包含雙引號（" 或 "），請一律改寫成全形引號「」或直接省略該引號，避免破壞 JSON 格式。引述中也不要包含未跳脫的特殊符號。

嚴格按照以下 JSON 格式輸出，禁止任何額外文字、解釋或 markdown code block：
{
  "place_name": "${placeName}",
  "aspects": {
    "A_facility": {
      "pros": [{"point":"","prevalence":"","quote":""}],
      "cons": [{"point":"","prevalence":"","quote":""}]
    },
    "B_historical_meaning": [{"point":"","prevalence":"","quote":""}],
    "C_emotion": [{"point":"","prevalence":"","quote":""}],
    "D_moral": [{"point":"","prevalence":"","quote":""}],
    "E_space_value": [{"point":"","prevalence":"","quote":""}],
    "F_political": [{"point":"","prevalence":"","quote":""}],
    "G_other": [{"point":"","prevalence":"","quote":""}]
  }
}`;

const userPrompt = `以下是評論對象「${placeName}」的一批 Google Maps 評論。
請依下列面向抽取觀點。面向定義：

A. 場所與設施體驗（單純評價）：觀光、建築、展覽、交通、環境、服務等實際體驗。區分 pros（優點）與 cons（缺點）。
B. 歷史意義（認知）：對此場所歷史價值、教育功能、紀念意義的理解。
C. 情緒（主觀感受）：評論者表達的情緒與心理感受，如震撼、悲傷、感動、莊嚴、緬懷。
D. 道德評價：對歷史人物、制度、事件或行為的道德判斷。
E. 空間場所評價：此場所作為公共空間、紀念場所或文化資產的角色與價值。
F. 政治表態：對當下政治議題、政權、歷史人物或政策的支持、反對或立場。
G. 其他：上述未涵蓋但反覆出現的其他面向，特定活動或事件引來的一批同質性評論，或是具特殊意義的少數觀點，如打卡活動、校外教學、異國視角。如果你處理的評論中，有非中文語言的評論，請特別保留其中幾則。

以下是這批評論：
${reviewsText}`;

return [{
  json: {
    place_name: placeName,
    place_id: placeID,
    batch_number: $('Loop over Reviews').context.currentRunIndex + 1,
    review_count: items.length,
    requestBody: {
      model: "claude-haiku-4-5",
      max_tokens: 10000,
      temperature: 0,
      system: systemPrompt,
      messages: [
        { role: "user", content: userPrompt }
      ]
    }
  }
}];

const items = $input.all();
const out = [];

for (const item of items) {
  const data = item.json;
  const content = data?.content?.[0]?.text;

  const placeID = $('Prompt (Final Summarize)').item.json.place_id;
  const placeName = $('Prompt (Final Summarize)').item.json.place_name;

  if (!content) {
    out.push({ json: { place_id: placeID, place_name: placeName,
      error: "No content in Anthropic response", raw: data } });
    continue;
  }

  out.push({
    json: {
      place_id: placeID.toString().trim(),
      place_name: placeName,
      summary: content.trim()
    }
  });
}

return out;

const total = items.length;

// 目標批次大小：100~200，盡量讓每批均等
let batchSize;

if (total <= 200) {
  // 少於 200 則: 全部跑一批就夠
  batchSize = total;
} else {
  // 計算需要幾批，每批不超過 200
  const minBatches = Math.ceil(total / 200);
  batchSize = Math.ceil(total / minBatches);
}

// 把 batchSize 寫回每個 item（Loop over Reviews 的 Batch Size 要用 expression 讀這個值）
return items.map(item => ({
  json: {
    ...item.json,
    batch_size: batchSize,
    total_reviews: total
  }
}));
